#include <iostream>
#include <stdexcept>
#include <type_traits>
#ifndef SIRKIT_INF_DEFINED
#error Shared INF guard is missing
#endif
#ifndef SIRKIT_GRAPH_TYPES_DEFINED
#error Shared weighted graph guard is missing
#endif
static_assert(INF == (std::int64_t{1} << 60));
static_assert(std::is_same_v<decltype(Edge::w), std::int64_t>);
int main() {
    std::size_t checks = 0;
    const auto require = [&](bool ok) { ++checks; if (!ok) throw std::runtime_error("combined SIMD library mismatch"); };
    std::vector<std::int64_t> original(64);
    for (std::size_t i = 0; i < original.size(); ++i) original[i] = static_cast<std::int64_t>(i % 7) - 3;
    auto f = original;
    subset_zeta_transform(f);
    for (unsigned s = 0; s < 64; ++s) {
        std::int64_t expected = 0;
        for (unsigned t = 0; t < 64; ++t) if ((t & s) == t) expected += original[t];
        require(f[s] == expected);
    }
    subset_mobius_transform(f); require(f == original);
    superset_zeta_transform(f);
    for (unsigned s = 0; s < 64; ++s) {
        std::int64_t expected = 0;
        for (unsigned t = 0; t < 64; ++t) if ((t & s) == s) expected += original[t];
        require(f[s] == expected);
    }
    superset_mobius_transform(f); require(f == original);
    std::vector<std::int64_t> expected_or(64), expected_and(64);
    for (unsigned i = 0; i < 64; ++i) for (unsigned j = 0; j < 64; ++j) {
        expected_or[i | j] += original[i] * original[j];
        expected_and[i & j] += original[i] * original[j];
    }
    require(bitwise_or_convolution(original, original) == expected_or);
    require(bitwise_and_convolution(original, original) == expected_and);
    PrimeSieve sieve(10000);
    std::uint64_t prime_count = 0;
    for (std::uint64_t n = 0; n <= 10000; ++n) {
        bool prime = n >= 2;
        for (std::uint64_t d = 2; d * d <= n; ++d) if (n % d == 0) { prime = false; break; }
        prime_count += prime;
        require(sieve.is_prime(n) == prime);
    }
    require(sieve.prime_count() == prime_count);
    const auto primes = sieve.primes(); require(primes.size() == prime_count);
    DynamicFenwickTree<int, std::int64_t> bit(8192);
    std::vector<std::int64_t> direct(8192);
    for (int i = 0; i < 256; ++i) { bit.add(i * 31, i % 11); direct[i * 31] += i % 11; }
    std::int64_t cumulative = 0;
    for (int i = 0; i <= 8192; ++i) {
        require(bit.sum(i) == cumulative);
        if (i < 8192) cumulative += direct[i];
    }
    require(bit.sum_all() == cumulative);
    DynamicFenwickTree2D<std::int64_t> grid(50000, 50000);
    for (int i = 0; i < 256; ++i) grid.add(i * 31, i * 53, i % 13);
    for (const int bound : {1, 3000, 10000, 50000}) {
        std::int64_t expected = 0;
        for (int i = 0; i < 256; ++i) if (i * 31 < bound && i * 53 < bound) expected += i % 13;
        require(grid.sum(bound, bound) == expected);
    }
    std::vector<std::vector<std::int64_t>> distance(35, std::vector<std::int64_t>(35, INF));
    WGraph graph(35);
    for (int i = 0; i < 35; ++i) {
        distance[i][i] = 0;
        if (i + 1 < 35) {
            distance[i][i + 1] = 1; distance[i + 1][i] = 2;
            graph[i].emplace_back(i + 1, 1); graph[i + 1].emplace_back(i, 2);
        }
    }
    auto with_path = distance;
    require(!FloydWarshall(distance));
    std::vector<std::vector<int>> next;
    require(!FloydWarshall(with_path, next)); require(distance == with_path);
    for (int i = 0; i < 35; ++i) for (int j = 0; j < 35; ++j)
        require(distance[i][j] == (j >= i ? j - i : 2 * (i - j)));
    require(FloydWarshallPath(next, 0, 34).size() == 35);
    std::vector<std::int64_t> single_source;
    Dijkstra(graph, single_source, 34);
    for (int i = 0; i < 35; ++i) require(single_source[i] == 2 * (34 - i));
    std::cout << "combined_simd: " << checks << " checks passed\n";
}
